import sys
from functools import lru_cache

MOD = 10**9 + 7

def sum_of_weights_partitions(n, k, weights):
    total_weight = sum(weights)

    @lru_cache(None)
    def count_partitions(i, k):
        if k == 1:
            return 1
        if i < k:
            return 0
        return (count_partitions(i - 1, k - 1) + count_partitions(i - 1, k)) % MOD

    @lru_cache(None)
    def calculate_weight(i, k):
        if k == 1:
            return (total_weight * weights[i - 1]) % MOD
        if i < k:
            return 0
        return (
            (k * calculate_weight(i - 1, k) % MOD + calculate_weight(i - 1, k - 1)) % MOD
        )

    result = 0
    for i in range(k, n + 1):
        partitions_count = count_partitions(i, k)
        weight_sum = calculate_weight(i, k)
        result = (result + partitions_count * weight_sum) % MOD

    return result

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    weights = list(map(int, data[2:]))

    result = sum_of_weights_partitions(n, k, weights)
    print(result)

if __name__ == "__main__":
    main()
